func:
// Opgeslagen config uit /data lezen en in global context zetten.
// De inlogvelden worden BEWUST NIET voorinvuld. Uitgang 1 = positie herstellen,
// uitgang 2 = laadpalen automatisch ophalen (als inloggegevens bekend zijn).
let cfg = {};
try { cfg = JSON.parse(msg.payload); } catch (e) { cfg = {}; }
let posMsg = null;
let fetchMsg = null;
let userMsg = null;
if (cfg && typeof cfg === 'object' && Object.keys(cfg).length) {
    global.set('zaptecCfg', cfg);
    node.status({ fill: 'green', shape: 'dot', text: 'config geladen' });
    if (cfg.position !== undefined && cfg.position !== null && cfg.position !== '') {
        posMsg = { payload: parseInt(cfg.position, 10) };
    }
    if (cfg.username && cfg.password) {
        fetchMsg = {};
    }
    if (cfg.username) {
        // Alleen de gebruikersnaam voorinvullen (wachtwoord bewust niet).
        userMsg = { payload: { username: cfg.username } };
    }
}
return [posMsg, fetchMsg, userMsg];

// Inloggegevens opslaan -> global context + bestand, en meteen de laadpalen ophalen.
// Uitgang 1 = bestand, uitgang 2 = melding, uitgang 3 = trigger laadpalen ophalen.
const p = msg.payload || {};
const prev = global.get('zaptecCfg') || {};
const cfg = {
    baseUrl: (p.baseUrl && String(p.baseUrl).trim()) || 'https://api.zaptec.com',
    username: String(p.username || '').trim(),
    password: String(p.password || ''),
    chargerId: prev.chargerId || ''
};
if (!cfg.username || !cfg.password) {
    node.status({ fill: 'red', shape: 'dot', text: 'vul gebruikersnaam + wachtwoord in' });
    return [null, { payload: 'Vul gebruikersnaam en wachtwoord in.' }, null];
}
if (prev.position !== undefined) cfg.position = prev.position;
global.set('zaptecCfg', cfg);
global.set('zaptecToken', null);
global.set('zaptecTokenExpiry', 0);
node.status({ fill: 'green', shape: 'dot', text: 'opgeslagen' });
return [
    { payload: JSON.stringify(cfg, null, 2), filename: "/data/zaptec-config.json" },
    { payload: 'Inloggegevens opgeslagen. Laadpalen worden opgehaald...' },
    {}
];

// Gekozen laadpaal opslaan (global + bestand) + melding. Slaat over als er niets wijzigt.
const id = msg.payload;
if (!id) { return null; }
const cfg = global.get('zaptecCfg') || {};
if (cfg.chargerId === id) { return null; }
cfg.chargerId = id;
global.set('zaptecCfg', cfg);
const names = global.get('zaptecChargerNames') || {};
node.status({ fill: 'green', shape: 'dot', text: 'laadpaal ' + (names[id] || id) });
return [
    { payload: JSON.stringify(cfg, null, 2), filename: "/data/zaptec-config.json" },
    { payload: 'Laadpaal ingesteld op: ' + (names[id] || id) }
];

// Gekozen positie opslaan (global context + persistent bestand). Uitgang 1 = bestand, 2 = melding.
const val = parseInt(msg.payload, 10);
const cfg = global.get('zaptecCfg') || {};
cfg.position = isNaN(val) ? 1 : val;
global.set('zaptecCfg', cfg);
const labels = { 0: 'AC-uit', 1: 'AC-in' };
node.status({ fill: 'green', shape: 'dot', text: 'positie ' + cfg.position });
return [
    { payload: JSON.stringify(cfg, null, 2), filename: "/data/zaptec-config.json" },
    { payload: 'Positie ingesteld op ' + (labels[cfg.position] || cfg.position) + '.' }
];

// Token ophalen om de laadpalen te tonen. Uitgang 1 = tokenrequest, uitgang 2 = melding.
const g = global.get('zaptecCfg') || {};
if (!g.username || !g.password) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'geen inloggegevens' });
    return [null, { payload: 'Vul eerst gebruikersnaam en wachtwoord in en klik Opslaan.' }];
}
const baseUrl = g.baseUrl || 'https://api.zaptec.com';
flow.set('listBaseUrl', baseUrl);
msg.method = 'POST';
msg.url = baseUrl + '/oauth/token';
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
msg.payload = 'grant_type=password'
    + '&username=' + encodeURIComponent(g.username)
    + '&password=' + encodeURIComponent(g.password)
    + '&scope=openid';
node.status({ fill: 'blue', shape: 'ring', text: 'ophalen...' });
return [msg, null];

// Uitgang 1 = chargers-request, uitgang 2 = foutmelding.
const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
if (!body.access_token) {
    const code = msg.statusCode || '?';
    node.status({ fill: 'red', shape: 'dot', text: 'auth mislukt (' + code + ')' });
    return [null, { payload: 'Inloggen bij Zaptec mislukt (HTTP ' + code + '). Controleer gebruikersnaam en wachtwoord.' }];
}
const baseUrl = flow.get('listBaseUrl') || 'https://api.zaptec.com';
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + body.access_token };
msg.url = baseUrl + '/api/chargers';
delete msg.payload;
return [msg, null];

// Vult de laadpaal-dropdown en kiest automatisch de actieve laadpaal.
// Uitgang 1 = dropdown (opties + selectie), uitgang 2 = melding, uitgang 3 = bestand.
const code = msg.statusCode;
if (code && code !== 200) {
    node.status({ fill: 'red', shape: 'dot', text: 'fout ' + code });
    return [null, { payload: 'Fout bij ophalen laadpalen (HTTP ' + code + ').' }, null];
}
const data = (msg.payload && Array.isArray(msg.payload.Data)) ? msg.payload.Data : [];
const options = data.map(function (c) {
    return { value: c.Id, label: (c.Name || '(naamloos)') + (c.IsOnline ? '' : ' - offline') };
});
const names = {};
data.forEach(function (c) { names[c.Id] = c.Name || c.Id; });
global.set('zaptecChargerNames', names);
global.set('zaptecChargerOptions', options);

const cfg = global.get('zaptecCfg') || {};
const ids = data.map(function (c) { return c.Id; });
let selected = cfg.chargerId;
if (!selected || ids.indexOf(selected) === -1) {
    selected = data.length ? data[0].Id : '';
}
cfg.chargerId = selected;
global.set('zaptecCfg', cfg);

node.status({ fill: 'green', shape: 'dot', text: data.length + ' laadpaal(en)' });
if (!data.length) {
    return [
        { options: [{ value: '', label: '(geen laadpalen gevonden)' }], payload: '' },
        { payload: 'Geen laadpalen gevonden voor dit account.' },
        null
    ];
}
return [
    { options: options, payload: selected },
    { payload: data.length + ' laadpaal(en) gevonden. Actief: ' + (names[selected] || selected) },
    { payload: JSON.stringify(cfg, null, 2), filename: "/data/zaptec-config.json" }
];

// Vult de UI wanneer de pagina wordt geopend (niet alleen bij deploy).
// Uitgang 1 = gebruikersnaam in formulier, 2 = positie, 3 = laadpaal-dropdown (uit cache),
// 4 = laadpalen ophalen als er nog geen cache is.
const cfg = global.get('zaptecCfg') || {};
const userMsg = cfg.username ? { payload: { username: cfg.username } } : null;
const posVal = (cfg.position !== undefined && cfg.position !== null && cfg.position !== '')
    ? parseInt(cfg.position, 10) : 1;
const posMsg = { payload: posVal };
const opts = global.get('zaptecChargerOptions');
let chargerMsg = null;
let fetchMsg = null;
if (opts && opts.length) {
    chargerMsg = { options: opts, payload: cfg.chargerId || opts[0].value };
} else if (cfg.username && cfg.password) {
    fetchMsg = {};
}
return [userMsg, posMsg, chargerMsg, fetchMsg];

// Adaptief pollen: snel bij live kijken, wat trager tijdens laden, traag bij idle.
const now = Date.now();
const S = 1000;
const iWatch = (parseInt(env.get('ZAPTEC_POLL_WATCHING_SEC'), 10) || 5) * S;
const iCharge = (parseInt(env.get('ZAPTEC_POLL_CHARGING_SEC'), 10) || 15) * S;
const iIdle = (parseInt(env.get('ZAPTEC_POLL_IDLE_SEC'), 10) || 120) * S;
const watchTimeout = (parseInt(env.get('ZAPTEC_WATCH_TIMEOUT_SEC'), 10) || 90) * S;

const lastAct = flow.get('lastVrmActivity') || 0;
const watching = (now - lastAct) < watchTimeout;
const charging = flow.get('chargeState') === 'charging';
const interval = watching ? iWatch : (charging ? iCharge : iIdle);

const lastFetch = flow.get('lastFetchTs') || 0;
if (now - lastFetch >= interval) {
    flow.set('lastFetchTs', now);
    const mode = watching ? 'live' : (charging ? 'laden' : 'idle');
    node.status({ fill: 'blue', shape: 'ring', text: 'poll (' + mode + ')' });
    return msg;
}
return null;

// Passieve live-kijk detectie: als de Venus MQTT-broker data stuurt, houdt iemand
// (VRM-app, GX-display of lokale app) de broker 'wakker'. Wij sturen zelf GEEN keepalive,
// dus we ontvangen alleen iets wanneer er daadwerkelijk een live kijker actief is.
flow.set('lastVrmActivity', Date.now());
return null;

// Configuratie uit VRM (global context), met terugval op omgevingsvariabelen.
const g = global.get('zaptecCfg') || {};
const cfg = {
    baseUrl: g.baseUrl || env.get('ZAPTEC_BASE_URL') || 'https://api.zaptec.com',
    username: g.username || env.get('ZAPTEC_USERNAME') || '',
    password: g.password || env.get('ZAPTEC_PASSWORD') || '',
    chargerId: g.chargerId || env.get('ZAPTEC_CHARGER_ID') || '',
    position: g.position
};
flow.set('zaptecCfg', cfg);

if (!cfg.username || !cfg.password || !cfg.chargerId) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'wacht op VRM-configuratie' });
    return null;
}

const token = global.get('zaptecToken');
const expiry = global.get('zaptecTokenExpiry') || 0;
if (token && Date.now() < (expiry - 60000)) {
    msg.access_token = token;
    node.status({ fill: 'green', shape: 'dot', text: 'token ok' });
    return [null, msg];
}

msg.method = 'POST';
msg.url = cfg.baseUrl + '/oauth/token';
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
msg.payload = 'grant_type=password'
    + '&username=' + encodeURIComponent(cfg.username)
    + '&password=' + encodeURIComponent(cfg.password)
    + '&scope=openid';
node.status({ fill: 'blue', shape: 'ring', text: 'token ophalen...' });
return [msg, null];

const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
if (!body.access_token) {
    const code = msg.statusCode || '?';
    node.status({ fill: 'red', shape: 'dot', text: 'auth mislukt (' + code + ')' });
    node.error('Zaptec: inloggen mislukt (HTTP ' + code + '). Controleer inloggegevens in VRM.', msg);
    return null;
}
global.set('zaptecToken', body.access_token);
global.set('zaptecTokenExpiry', Date.now() + ((Number(body.expires_in) || 3600) * 1000));
msg.access_token = body.access_token;
node.status({ fill: 'green', shape: 'dot', text: 'token vernieuwd' });
return msg;

const cfg = flow.get('zaptecCfg') || {};
const token = msg.access_token || global.get('zaptecToken');
if (!token) { node.error('Geen Zaptec-token beschikbaar.', msg); return null; }
if (!cfg.chargerId) {
    node.status({ fill: 'red', shape: 'dot', text: 'charger-id ontbreekt' });
    return null;
}
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + token };
msg.url = cfg.baseUrl + '/api/chargers/' + encodeURIComponent(cfg.chargerId) + '/state';
delete msg.payload;
return msg;

// Zet Zaptec state-observaties om naar payload voor een Victron energiemeter (rol: EV charger).
const obs = Array.isArray(msg.payload)
    ? msg.payload
    : (msg.payload && Array.isArray(msg.payload.Data) ? msg.payload.Data : []);
if (!obs.length) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'geen state ontvangen' });
    return null;
}

// Observaties indexeren op StateId.
const s = {};
for (const o of obs) {
    if (o && o.StateId !== undefined && o.StateId !== null) {
        s[o.StateId] = o.ValueAsString;
    }
}

const num = (v) => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const r = (v, d) => { const f = Math.pow(10, d === undefined ? 0 : d); return Math.round((v || 0) * f) / f; };

// Zaptec observatie-ID's (zie https://api.zaptec.com/api/constants).
const v1 = num(s[501]), v2 = num(s[502]), v3 = num(s[503]); // Voltage L1/L2/L3 (V)
const i1 = num(s[507]), i2 = num(s[508]), i3 = num(s[509]); // Current L1/L2/L3 (A)
let pTotal = num(s[513]);                                    // TotalChargePower (W)

// Vermogen per fase (schijnbaar vermogen V*I; EV-laden benadert cos phi = 1).
const p1 = v1 * i1, p2 = v2 * i2, p3 = v3 * i3;
const pSum = p1 + p2 + p3;
if (!pTotal) pTotal = pSum;

// Online-status (IsOnline = observatie -2). Als afwezig: aannemen online.
let online = 1;
if (s[-2] !== undefined) online = (s[-2] === '1' || s[-2] === 1) ? 1 : 0;

// Totale (levensduur) energie in kWh voor /Ac/Energy/Forward.
let ef = flow.get('zaptecEnergyForward');
if (typeof ef !== 'number' || isNaN(ef)) ef = 0;
const nowMs = Date.now();
const lastMs = flow.get('zaptecEnergyTs') || nowMs;

// Probeer de officiele gesigneerde meterstand (OCMF, observatie 554) te lezen.
function parseOcmfKwh(str) {
    if (!str || typeof str !== 'string' || str.indexOf('OCMF') === -1) return null;
    try {
        const parts = str.split('|');
        for (const p of parts) {
            const t = p.trim();
            if (t.charAt(0) === '{' && t.indexOf('"RD"') !== -1) {
                const j = JSON.parse(t);
                if (Array.isArray(j.RD) && j.RD.length) {
                    const last = j.RD[j.RD.length - 1];
                    if (last && last.RV !== undefined && last.RV !== null) {
                        const val = parseFloat(last.RV);
                        if (!isNaN(val)) return val;
                    }
                }
            }
        }
    } catch (e) { /* negeren, val terug op integratie */ }
    return null;
}

const ocmf = parseOcmfKwh(s[554]);
if (ocmf !== null && ocmf >= ef) {
    ef = ocmf; // gebruik de officiele meterstand indien beschikbaar
} else {
    // Terugval: integreer vermogen over tijd. Guard voorkomt sprongen na downtime.
    const dtH = (nowMs - lastMs) / 3600000;
    if (dtH > 0 && dtH < 1) ef += (pTotal * dtH) / 1000;
}
flow.set('zaptecEnergyForward', ef);
flow.set('zaptecEnergyTs', nowMs);

// Positie in het Victron-systeem (via VRM-formulier of env). 0 = AC-uit 1, 1 = AC-in 1, 2 = AC-uit 2.
const _cfg = flow.get('zaptecCfg') || {};
let position = (_cfg.position !== undefined && _cfg.position !== null && _cfg.position !== '')
    ? parseInt(_cfg.position, 10)
    : parseInt(env.get('ZAPTEC_METER_POSITION'), 10);
msg.payload = {
    Connected: online,
    Position: isNaN(position) ? 1 : position,
    'Ac/Power': r(pTotal, 1),
    'Ac/Energy/Forward': r(ef, 3),
    'Ac/L1/Voltage': r(v1, 1),
    'Ac/L1/Current': r(i1, 2),
    'Ac/L1/Power': r(p1, 1),
    'Ac/L2/Voltage': r(v2, 1),
    'Ac/L2/Current': r(i2, 2),
    'Ac/L2/Power': r(p2, 1),
    'Ac/L3/Voltage': r(v3, 1),
    'Ac/L3/Current': r(i3, 2),
    'Ac/L3/Power': r(p3, 1)
};

const _mode = parseInt(s[710], 10);
const _charging = (_mode === 3) || (pTotal > 100);
flow.set('chargeState', _charging ? 'charging' : 'idle');

node.status({ fill: online ? (_charging ? 'green' : 'blue') : 'grey', shape: 'dot', text: (_charging ? 'laden ' : 'idle ') + r(pTotal, 0) + ' W | ' + r(ef, 2) + ' kWh' });
return msg;

// Bouwt een statusregel voor het VRM-dashboard.
const p = msg.payload || {};
const w = p['Ac/Power'];
const kwh = p['Ac/Energy/Forward'];
const on = p.Connected ? 'online' : 'offline';
const t = new Date().toLocaleTimeString('nl-NL');
msg.payload = 'Laatste uitlezing: ' + (w != null ? w : '?') + ' W, ' + (kwh != null ? kwh : '?') + ' kWh (' + on + ') @ ' + t;
return msg;

const e = (msg.error && msg.error.message) ? msg.error.message : 'onbekende fout';
msg.payload = 'Fout: ' + e + ' @ ' + new Date().toLocaleTimeString('nl-NL');
return msg;
